import csv,io,re
from datetime import date
from decimal import Decimal
from .models import Entry
_CURRENCY_RE = re.compile(r'^[A-Z]{3}$')
def _normalize_currency(value):
    if value is None:
        return 'USD'
    code = str(value).strip().upper()
    if not code:
        return 'USD'
    if not _CURRENCY_RE.match(code):
        raise ValueError(f'invalid currency code: {value!r}')
    return code
def parse_csv(text):
    return [Entry(row['account'],Decimal(row['amount']),date.fromisoformat(row['day']),row.get('status') or 'posted',_normalize_currency(row.get('currency'))) for row in csv.DictReader(io.StringIO(text))]

import json
from .parser import parse_csv
from .summary import total, totals_by_currency
def render_report(text, *, by_currency=False, start=None, end=None):
    if by_currency:
        data = totals_by_currency(parse_csv(text), start=start, end=end, include_pending=True)
        return json.dumps({'totals': {c: format(a, '.2f') for c, a in sorted(data.items())}}, sort_keys=True)
    return json.dumps({'total':format(total(parse_csv(text)),'.2f')},sort_keys=True)

from datetime import date
from decimal import Decimal
def total(entries):
    return sum((e.amount for e in entries),Decimal('0'))
def totals_by_currency(entries, start=None, end=None, include_pending=False):
    if start is not None and end is not None and start > end:
        raise ValueError('start must be on or before end')
    def _in_range(e):
        if start is not None and e.day < start:
            return False
        if end is not None and e.day > end:
            return False
        return True
    result = {}
    for e in entries:
        if not include_pending and e.status != 'posted':
            continue
        if not _in_range(e):
            continue
        result[e.currency] = result.get(e.currency, Decimal('0')) + e.amount
    return result

